function escapeHtml(s) {
  return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}
function safeGet(nodeName, path) {
  try {
    const node = $(nodeName);
    if (node.first()) { return path(node.first().json); }
  } catch (e) { return undefined; }
  return undefined;
}
const STALE_DAYS = 7;
const now = Date.now();
const telegramChatId = safeGet('Profil laden (FollowUp)', j => j.telegram_chat_id) || null;
const dealsRaw = safeGet('HubSpot Deals suchen (FollowUp)', j => j.results) || [];
const staleDeals = dealsRaw.map(d => {
  const lastMod = d.properties?.hs_lastmodifieddate ? new Date(d.properties.hs_lastmodifieddate).getTime() : null;
  const days = lastMod ? Math.floor((now - lastMod) / 86400000) : null;
  return { name: d.properties?.dealname, days };
}).filter(d => d.days !== null && d.days > STALE_DAYS);
const staleLeads = $('FollowUp Leads zusammenfuehren').all().map(i => i.json).filter(l => l && l.name);
if (!staleDeals.length && !staleLeads.length) {
  return [{ json: { reply: '', telegram_chat_id: telegramChatId } }];
}
let text = 'Follow-Up Guard — das braucht Aufmerksamkeit:\n';
if (staleDeals.length) {
  text += '\nDeals ohne Bewegung:\n' + staleDeals.map(d => `• ${d.name} (${d.days}d)`).join('\n');
}
if (staleLeads.length) {
  text += '\n\nFaellige Leads:\n' + staleLeads.map(l => {
    let line = `• ${l.name}`;
    if (l.company) line += ` (${l.company})`;
    if (l.priority) line += ` — Prioritaet ${l.priority}`;
    const days = l.overdue_days;
    if (typeof days === 'number') {
      if (days >= 14) line += ` — 🔴 seit ${days}d ignoriert, bitte reagieren`;
      else if (days >= 5) line += ` — ⚠️ ueberfaellig seit ${days}d`;
      else line += ` — faellig seit ${days}d`;
    }
    if (l.draft) {
      line += `\n  Nachrichtenvorschlag:\n  <pre><code class="language-plain">${escapeHtml(l.draft)}</code></pre>`;
    }
    return line;
  }).join('\n\n');
}
return [{ json: { reply: text, telegram_chat_id: telegramChatId } }];

const profile = $('Profil laden (Weekly)').first().json.profile || {};
const active = profile.weekly_review_aktiv === 'true'; // Default false (opt-in)
const targetDay = parseInt(profile.weekly_review_tag || '1', 10); // ISO Wochentag, Montag=1
const targetTime = profile.weekly_review_uhrzeit || '08:00';
const [targetHour, targetMinuteRaw] = targetTime.split(':').map(Number);
const targetMinute = targetMinuteRaw || 0;
const berlinNow = new Date(new Date().toLocaleString('en-US', { timeZone: 'Europe/Berlin' }));
const jsDay = berlinNow.getDay(); // 0=So..6=Sa
const isoDay = jsDay === 0 ? 7 : jsDay;
const currentHour = berlinNow.getHours();
const currentMinute = berlinNow.getMinutes();
const bucket5 = m => Math.floor(m / 5) * 5;
// ISO-Woche fuer Dedupe-Key (z.B. '2026-W35')
const d2 = new Date(Date.UTC(berlinNow.getFullYear(), berlinNow.getMonth(), berlinNow.getDate()));
const dayNum = (d2.getUTCDay() + 6) % 7;
d2.setUTCDate(d2.getUTCDate() - dayNum + 3);
const firstThursday = new Date(Date.UTC(d2.getUTCFullYear(), 0, 4));
const weekNum = 1 + Math.round(((d2 - firstThursday) / 86400000 - 3 + ((firstThursday.getUTCDay() + 6) % 7)) / 7);
const isoWeek = `${d2.getUTCFullYear()}-W${String(weekNum).padStart(2, '0')}`;
return [{ json: { match: active && isoDay === targetDay && currentHour === targetHour && bucket5(currentMinute) === bucket5(targetMinute), isoWeek } }];;

