  return undefined;
}
const STALE_DAYS = 7;
const now = Date.now();
const telegramChatId = safeGet('Profil laden (Weekly)', j => j.telegram_chat_id) || null;
const done = $('Erledigte Memory laden (Weekly)').all().map(i => i.json).filter(m => m && m.content);
const dealsRaw = safeGet('HubSpot Deals suchen (Weekly)', j => j.results) || [];
const staleDeals = dealsRaw.map(d => {
  const lastMod = d.properties?.hs_lastmodifieddate ? new Date(d.properties.hs_lastmodifieddate).getTime() : null;
  const days = lastMod ? Math.floor((now - lastMod) / 86400000) : null;
  return { name: d.properties?.dealname, days };
}).filter(d => d.days !== null && d.days > STALE_DAYS);
const newLeads = $('Neue Leads laden (Weekly)').all().map(i => i.json).filter(l => l && l.name);
let text = 'Wochen-Review:\n';
text += `\nErledigt diese Woche: ${done.length ? done.length : 'nichts erfasst'}`;
if (done.length) text += '\n' + done.slice(0, 10).map(m => `• [${m.type}] ${m.content}`).join('\n');
text += `\n\nNeue Leads diese Woche: ${newLeads.length || 'keine'}`;
if (newLeads.length) text += '\n' + newLeads.map(l => `• ${l.name}${l.company ? ` (${l.company})` : ''}`).join('\n');
text += `\n\nDeals ohne Bewegung (>${STALE_DAYS}d): ${staleDeals.length || 'keine'}`;
if (staleDeals.length) text += '\n' + staleDeals.map(d => `• ${d.name} (${d.days}d)`).join('\n');
return [{ json: { reply: text, telegram_chat_id: telegramChatId } }];

const profile = $('Profil laden (PreMeeting)').first().json.profile || {};
const active = profile.premeeting_snapshot_aktiv === 'true'; // Default false (opt-in)
const domain = (profile.company_domain || '').toLowerCase().trim();
return [{ json: { match: active && domain.length > 0, domain } }];

const domain = $('Pre-Meeting Gate').first().json.domain;
const events = $json.events || [];
for (const e of events) {
  const attendees = (e.attendees || []).map(a => a.emailAddress).filter(Boolean);
  const external = attendees.find(a => {
    const addr = (a.address || '').toLowerCase();
    const atDomain = addr.split('@')[1] || '';
    return atDomain && atDomain !== domain;
  });
  if (external) {
    return [{ json: {
      found: true,
      eventId: e.id,
      subject: e.subject || '(ohne Titel)',
      start: e.start?.dateTime || null,
      attendeeEmail: external.address,
      attendeeName: external.name || external.address
    } }];
  }
}
return [{ json: { found: false } }];

