function safeGet(nodeName, path) {
  try {
    const node = $(nodeName);
    if (node.first()) { return path(node.first().json); }
  } catch (e) { return undefined; }
  return undefined;
}
const meeting = $('Externe Meetings filtern').first().json;
const userName = safeGet('Profil laden (PreMeeting)', j => j.profile?.name) || 'der Nutzer';
const telegramChatId = safeGet('Profil laden (PreMeeting)', j => j.telegram_chat_id) || null;
const emails = $('Email-Cache laden (PreMeeting)').all().map(i => i.json).filter(e => e && e.zusammenfassung);
const contactsRaw = safeGet('HubSpot Kontakt suchen (PreMeeting)', j => j.results) || [];
const hubspotContact = contactsRaw[0]?.properties || null;
const leads = $('Lead-Match laden (PreMeeting)').all().map(i => i.json).filter(l => l && l.name);
const systemPrompt = 'Du bist Jonas. Baue ein kurzes Pre-Meeting-Briefing auf Deutsch (max 4-5 Zeilen) fuer ' + userName + ', '
  + 'der gleich ein externes Meeting hat. Nutze NUR die gelieferten Fakten, erfinde nichts. '
  + 'Wenn zu einer Quelle nichts vorliegt, einfach weglassen statt das zu erwaehnen. Direkt und knapp, wie ein guter Assistent kurz vorm Meeting.';
const userMessage = `Meeting: ${meeting.subject} um ${meeting.start}\n`
  + `Teilnehmer: ${meeting.attendeeName} (${meeting.attendeeEmail})\n`
  + `HubSpot-Kontakt: ${hubspotContact ? JSON.stringify(hubspotContact) : 'kein Treffer'}\n`
  + `Gespeicherte Leads: ${leads.length ? JSON.stringify(leads) : 'kein Treffer'}\n`
  + `Aktuelle Mails von diesem Kontakt: ${emails.length ? JSON.stringify(emails) : 'keine'}`;
return [{ json: { systemPrompt, userMessage, subject: meeting.subject, telegram_chat_id: telegramChatId } }];

const text = $json.text || '';
const kontext = $('Pre-Meeting Kontext bauen').first().json;
const subject = kontext.subject;
const reply = text ? `Gleich: ${subject}\n\n${text}` : `Gleich: ${subject} — konnte den Kontext gerade nicht zusammenfassen.`;
return [{ json: { reply, telegram_chat_id: kontext.telegram_chat_id } }];

const profile = $('Profil laden (AbendRecap)').first().json.profile || {};
const active = profile.abend_recap_aktiv === 'true'; // Default false (opt-in)
const targetTime = profile.abend_recap_uhrzeit || '19:00';
const [targetHour, targetMinuteRaw] = targetTime.split(':').map(Number);
const targetMinute = targetMinuteRaw || 0;
const berlinNow = new Date(new Date().toLocaleString('en-US', { timeZone: 'Europe/Berlin' }));
const currentHour = berlinNow.getHours();
const currentMinute = berlinNow.getMinutes();
const bucket5 = m => Math.floor(m / 5) * 5;
return [{ json: { match: active && currentHour === targetHour && bucket5(currentMinute) === bucket5(targetMinute) } }];

const profile = $('Profil laden (AbendRecap)').first().json.profile || {};
const wasPending = profile.abend_recap_pending === 'true';
const currentStreak = parseInt(profile.abend_recap_miss_streak || '0', 10);
const newStreak = wasPending ? currentStreak + 1 : currentStreak;
const shouldDisable = newStreak >= 5;
return [{ json: { newStreak, shouldDisable } }];

// Rollout abgeschlossen 06.09.2026 (Nutzer: "Abend-Recap Smarter erfolgreich lang genug getestet").
const requiredChannels = ['internal', 'beta', 'stable'];
const tenantChannel = $('Aktive Tenants laden').item.json.channel || 'stable';
return [{ json: { ...$json, channelGateOpen: requiredChannels.includes(tenantChannel) } }];

function safeGet(fn, fallback) { try { return fn(); } catch (e) { return fallback; } }

const memoryItems = safeGet(() => $('Faellige Memory laden (AbendRecap)').all().map(i => i.json).filter(r => r.id), []);
const events = safeGet(() => $('Events entpacken (AbendRecap)').first().json.events, []) || [];

const askedItems = [];
const parts = [];

for (const m of memoryItems) {
  askedItems.push({ kind: 'memory', id: m.id, label: m.content });
  parts.push(`"${m.content}" — durch?`);
}
for (const e of events) {
  const label = e.subject || '(ohne Titel)';
  askedItems.push({ kind: 'event', id: e.id, label });
  const time = e.start?.dateTime ? new Date(e.start.dateTime).toLocaleTimeString('de-DE', { hour: '2-digit', minute: '2-digit', timeZone: 'Europe/Berlin' }) : '';
  parts.push(`Termin "${label}"${time ? ' um ' + time + ' Uhr' : ''} — gelaufen?`);
}

const question = parts.length > 0
  ? 'Kurzer Rückblick auf heute: ' + parts.join(' ')
  : 'Wie war dein Tag heute?';

return [{ json: { question, itemCount: askedItems.length, askedItems: JSON.stringify(askedItems) } }];;

const profile = $json.profile || {};
const featureActive = profile.termin_radar_aktiv === 'true';
return { json: { ...$json, featureActive } };

const now = $now.setZone('Europe/Berlin');
const onSchedule = (now.hour % 3 === 0) && (now.minute < 5);
return { json: { ...$json, scanDran: onSchedule } };

const requiredChannels = ['internal', 'beta'];
const tenantChannel = $('Aktive Tenants laden').item.json.channel || 'stable';
return { json: { ...$json, channelGateOpen: requiredChannels.includes(tenantChannel) } };

const events = $input.first().json.value || [];
return events.map(e => ({ json: {
  eventId: e.id,
  subject: e.subject || '(ohne Titel)',
  start: e.start?.dateTime || null,
  end: e.end?.dateTime || null,
  attendees: (e.attendees || []).map(a => a.emailAddress?.address).filter(Boolean)
} }));

function safeGet(fn, fallback) { try { return fn(); } catch (e) { return fallback; } }
const ev = $json;
const crmMatch = safeGet(() => $('CRM-Kontext laden (Wichtig)').first().json, {});
const hasMatch = !!(crmMatch.contactId || crmMatch.dealId || crmMatch.leadId);
const matchLabel = crmMatch.contactName || crmMatch.dealName || crmMatch.leadName || null;
const startLabel = ev.start ? new Date(ev.start).toLocaleString('de-DE', { dateStyle: 'short', timeStyle: 'short', timeZone: 'Europe/Berlin' }) : 'unbekannt';
const systemPrompt = 'Du bist Jonas, ein AI Ops-Agent fuer Immobilienmakler. Beurteile EINEN Kalendertermin.'
  + '\nTermin: "' + ev.subject + '", Zeit: ' + startLabel
  + '\nExterne Teilnehmer erkannt: ' + (ev.attendees && ev.attendees.length ? 'ja (' + ev.attendees.length + ')' : 'nein')
  + '\nCRM-Treffer zu einem Teilnehmer vorhanden: ' + (hasMatch ? 'ja (' + matchLabel + ')' : 'nein')
  + '\n\nIst dieser Termin fuer einen Immobilienmakler wichtig genug, um den Nutzer proaktiv per Telegram darauf hinzuweisen (z.B. Kundentermin, Besichtigung, Notartermin, Kaufvertrag — NICHT interne/private Termine, NICHT generische Blocker wie "Mittagspause")? '
  + '\n\nGib AUSSCHLIESSLICH ein JSON-Objekt zurueck, keine weitere Erklaerung, kein Markdown: '
  + '{"important": true|false, "reason": "<max. 1 kurzer Satz Deutsch, Begruendung>"}';
return { json: { systemPrompt, userMessage: ev.subject, hasMatch, matchLabel, eventId: ev.eventId, subject: ev.subject, startLabel, telegram_chat_id: crmMatch.telegram_chat_id || null, tenant_id: crmMatch.tenant_id || null } };

const raw = $json.text || '';
let important = false, reason = '';
try {
  const start = raw.indexOf('{');
  const end = raw.lastIndexOf('}');
  const parsed = JSON.parse(raw.slice(start, end + 1));
  important = parsed.important === true;
  reason = parsed.reason || '';
} catch (e) { }
return { json: { important, reason } };

const domain = ($('Profil laden (Wichtig)').first().json.profile?.company_domain || '').toLowerCase().trim();
const attendees = $json.attendees || [];
const external = attendees.find(addr => {
  const atDomain = (addr || '').toLowerCase().split('@')[1] || '';
  return domain && atDomain && atDomain !== domain;
});
return { json: { ...$json, hasExternal: !!external, attendeeEmail: external || null } };

