function safeGet(fn, fallback) { try { return fn(); } catch (e) { return fallback; } }
const contactsRaw = safeGet(() => $('HubSpot Kontakt suchen (Wichtig)').first().json.results, []) || [];
const hubspotContact = contactsRaw[0] || null;
const leads = safeGet(() => $('Lead-Match laden (Wichtig)').all().map(i => i.json), []).filter(l => l && l.name);
const lead = leads[0] || null;

const contactId = hubspotContact ? hubspotContact.id : null;
const contactName = hubspotContact ? [hubspotContact.properties?.firstname, hubspotContact.properties?.lastname].filter(Boolean).join(' ') || hubspotContact.properties?.company || null : null;
const leadId = lead ? 'lead:' + lead.name : null;
const leadName = lead ? lead.name : null;

const telegramChatId = safeGet(() => $('Profil laden (Wichtig)').first().json.telegram_chat_id, null);
const tenantId = safeGet(() => $('Profil laden (Wichtig)').first().json.tenant_id, null);

return [{ json: { contactId, contactName, dealId: null, dealName: null, leadId, leadName, telegram_chat_id: telegramChatId, tenant_id: tenantId } }];

const b = $('Wichtig-Beurteilung bauen').first().json;
const a = $('Wichtig-Antwort parsen').first().json;
const messageText = "📌 Termin \"" + b.subject + "\" um " + b.startLabel + " Uhr. " + a.reason + " Soll ich dir Infos zu " + b.matchLabel + " raussuchen?";
return { json: { ...$json, messageText, eventId: b.eventId, matchLabel: b.matchLabel, telegram_chat_id: b.telegram_chat_id, tenant_id: b.tenant_id } };

const l = $json;
const notesLine = l.notes ? `Notizen: ${l.notes}` : 'Notizen: (keine vorhanden)';
const langCode = (l.language || 'de').toLowerCase();
const systemPrompt = `Du entwirfst eine kurze, direkt kopierbare Nachfass-Nachricht (LinkedIn/Email) fuer einen faelligen Lead. Nutze AUSSCHLIESSLICH die folgenden Informationen -- erfinde keine Details, keine Zahlen, keine Zusagen die nicht genannt wurden.

Kontakt: ${l.name}${l.company ? ' (' + l.company + ')' : ''}
${notesLine}
Ueberfaellig seit: ${l.overdue_days ?? 0} Tag(en)

Schreibe eine kurze, freundliche, direkt versendbare Nachfass-Nachricht (2-4 Saetze) GENAU in der Sprache mit ISO-639-1-Code "${langCode}" -- dieser Code ist bereits bekannt (beim Erfassen des Kontakts ermittelt), nicht neu raten oder aus den Notizen ableiten. KEINE Anrede-Floskeln wie "Sehr geehrte/r", locker-professionell. Antworte NUR mit dem Nachrichtentext, keine Erklaerung, keine Anfuehrungszeichen drumherum.`;
return { json: { name: l.name, company: l.company, priority: l.priority, overdue_days: l.overdue_days, systemPrompt } };

const src = $('FollowUp Draft Prompt bauen').item.json;
let draft = null;
if (!$json.error) {
  const t = ($json.text || '').trim();
  draft = t || null;
}
return { json: { name: src.name, company: src.company, priority: src.priority, overdue_days: src.overdue_days, draft } };
